sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* =========================================================
   MEALCARE — WIDGET CONTENT CSS
   Professional Dark Frame Theme
   ServiceNow Compatible
   HTML unchanged — same class names
   Styling only
   ========================================================= */


/* =========================================================
   1. FOUNDATION
   ========================================================= */

.cfa-hero,
.cfa-welcome,
.cfa-services,
.cfa-about,
.cfa-contact {
  position: relative;
  width: 100%;
  color: #64748B;
  font-family: "Segoe UI", Arial, sans-serif;
  box-sizing: border-box;
}

.cfa-hero *,
.cfa-welcome *,
.cfa-services *,
.cfa-about *,
.cfa-contact *,
.cfa-hero *::before,
.cfa-welcome *::before,
.cfa-services *::before,
.cfa-about *::before,
.cfa-contact *::before,
.cfa-hero *::after,
.cfa-welcome *::after,
.cfa-services *::after,
.cfa-about *::after,
.cfa-contact *::after {
  box-sizing: border-box;
}

.cfa-hero a {
  text-decoration: none;
}


/* =========================================================
   2. SECTION LABEL
   ========================================================= */

.cfa-section-label {
  display: inline-flex;
  align-items: center;

  margin-bottom: 18px;
  padding: 7px 16px 7px 12px;

  color: #1D4ED8;

  background: #EFF6FF;

  border: 1px solid #DBEAFE;

  border-radius: 999px;

  font-size: 13px;
  font-weight: 700;
}

.cfa-section-label::before {
  content: "";

  width: 8px;
  height: 8px;

  margin-right: 9px;

  background: #2563EB;

  border-radius: 50%;
}


/* =========================================================
   3. HERO
   ========================================================= */

.cfa-hero {
  min-height: 720px;

  display: flex;
  align-items: center;

  overflow: hidden;

  padding: 115px 0 125px;

  background:
    radial-gradient(
      circle at 85% 18%,
      rgba(96, 165, 250, 0.22),
      transparent 34%
    ),
    radial-gradient(
      circle at 5% 95%,
      rgba(37, 99, 235, 0.16),
      transparent 34%
    ),
    linear-gradient(
      140deg,
      #0F172A 0%,
      #1E293B 55%,
      #172554 100%
    );
}


/* =========================================================
   4. HERO GRID
   ========================================================= */

.cfa-hero::before {
  content: "";

  position: absolute;
  inset: 0;

  pointer-events: none;

  background-image:
    linear-gradient(
      rgba(96, 165, 250, 0.045) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(96, 165, 250, 0.045) 1px,
      transparent 1px
    );

  background-size: 48px 48px;

  mask-image:
    linear-gradient(
      to bottom,
      #000,
      transparent 85%
    );

  -webkit-mask-image:
    linear-gradient(
      to bottom,
      #000,
      transparent 85%
    );
}


/* =========================================================
   5. HERO GLASS PANEL
   ========================================================= */

.cfa-hero::after {
  content: "";

  position: absolute;

  right: 8%;
  top: 50%;

  width: 320px;
  height: 230px;

  transform:
    translateY(-50%)
    rotate(4deg);

  border-radius: 28px;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.10),
      rgba(96, 165, 250, 0.05)
    );

  border:
    1px solid rgba(255, 255, 255, 0.16);

  box-shadow:
    0 30px 70px rgba(0, 0, 0, 0.30),
    inset 0 1px 0 rgba(255, 255, 255, 0.15);

  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);

  pointer-events: none;

  animation:
    cfaFloat 7s ease-in-out infinite alternate;
}


/* =========================================================
   6. SMALL HERO CARD
   ========================================================= */

.cfa-hero-inner::after {
  content: "";

  position: absolute;

  right: -40px;
  top: 50%;

  width: 170px;
  height: 120px;

  transform:
    translateY(40%)
    rotate(-6deg);

  border-radius: 22px;

  background:
    linear-gradient(
      145deg,
      #60A5FA,
      #2563EB
    );

  box-shadow:
    0 14px 34px rgba(37, 99, 235, 0.32);

  opacity: 0.92;

  pointer-events: none;

  animation:
    cfaFloatTwo 8s ease-in-out infinite alternate;
}


/* =========================================================
   7. HERO GLOWS
   ========================================================= */

.cfa-hero-glow {
  position: absolute;

  border-radius: 50%;

  pointer-events: none;

  filter: blur(40px);
}

.cfa-hero-glow-one {
  width: 460px;
  height: 460px;

  right: -160px;
  top: -200px;

  background:
    rgba(37, 99, 235, 0.22);
}

.cfa-hero-glow-two {
  width: 420px;
  height: 420px;

  left: -200px;
  bottom: -240px;

  background:
    rgba(96, 165, 250, 0.14);
}


/* =========================================================
   8. HERO INNER
   ========================================================= */

.cfa-hero-inner {
  position: relative;
  z-index: 5;

  width: 100%;
  max-width: 1180px;

  margin: 0 auto;

  padding: 0 28px;
}


/* =========================================================
   9. HERO BADGE
   ========================================================= */

.cfa-hero-badge {
  display: inline-flex;
  align-items: center;

  margin-bottom: 26px;

  padding: 9px 18px;

  color: #93C5FD;

  background:
    rgba(96, 165, 250, 0.08);

  border:
    1px solid rgba(96, 165, 250, 0.25);

  border-radius: 999px;

  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);

  font-size: 13px;
  font-weight: 600;

  letter-spacing: 0.3px;
}

.cfa-hero-badge::before {
  content: "";

  width: 8px;
  height: 8px;

  margin-right: 10px;

  background: #60A5FA;

  border-radius: 50%;

  box-shadow:
    0 0 0 4px rgba(96, 165, 250, 0.16);

  animation:
    cfaPulse 2.2s ease-in-out infinite;
}


/* =========================================================
   10. HERO HEADING
   ========================================================= */

.cfa-hero h1 {
  position: relative;

  max-width: 820px;

  margin: 0 0 32px;

  color: #FFFFFF;

  font-size:
    clamp(46px, 6vw, 80px);

  line-height: 1.02;

  letter-spacing: -3px;

  font-weight: 800;

  text-wrap: balance;
}

.cfa-hero h1::after {
  content: "";

  position: absolute;

  left: 3px;
  bottom: -16px;

  width: 96px;
  height: 5px;

  background:
    linear-gradient(
      90deg,
      #2563EB,
      #60A5FA,
      transparent
    );

  border-radius: 99px;
}


/* =========================================================
   11. HERO DESCRIPTION
   ========================================================= */

.cfa-hero-inner > p {
  max-width: 640px;

  margin: 0 0 36px;

  color:
    rgba(255, 255, 255, 0.76);

  font-size: 18px;

  line-height: 1.75;
}


/* =========================================================
   12. HERO BUTTON
   ========================================================= */

.cfa-hero-btn {
  position: relative;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  min-height: 56px;

  padding: 0 30px;

  overflow: hidden;

  background:
    linear-gradient(
      135deg,
      #2563EB,
      #3B82F6
    );

  color: #FFFFFF;

  border-radius: 12px;

  box-shadow:
    0 14px 34px rgba(37, 99, 235, 0.30);

  font-size: 15px;

  font-weight: 800;

  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.cfa-hero-btn::before {
  content: "";

  position: absolute;

  top: 0;
  left: -120%;

  width: 70%;
  height: 100%;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255, 255, 255, 0.35),
      transparent
    );

  transform: skewX(-20deg);

  transition:
    left 0.65s ease;
}

.cfa-hero-btn:hover::before {
  left: 140%;
}

.cfa-hero-btn:hover {
  color: #FFFFFF;

  transform:
    translateY(-4px);

  box-shadow:
    0 20px 44px rgba(37, 99, 235, 0.40);
}

.cfa-hero-btn:active {
  transform:
    translateY(-1px)
    scale(0.98);
}

.cfa-hero-btn span {
  margin-left: 12px;

  font-size: 19px;

  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.cfa-hero-btn:hover span {
  transform:
    translateX(5px);
}


/* =========================================================
   13. HERO NOTE
   ========================================================= */

.cfa-hero-note {
  display: flex;
  align-items: center;

  margin-top: 26px;

  color:
    rgba(147, 197, 253, 0.85);

  font-size: 13px;

  line-height: 1.7;
}

.cfa-hero-note span {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 24px;
  height: 24px;

  margin-right: 9px;

  background:
    rgba(37, 99, 235, 0.16);

  color: #60A5FA;

  border-radius: 50%;

  font-weight: 800;
}


/* =========================================================
   14. WELCOME
   ========================================================= */

.cfa-welcome {
  padding: 105px 0;

  background:
    linear-gradient(
      180deg,
      #FFFFFF 0%,
      #F8FAFC 100%
    );
}

.cfa-welcome-inner {
  position: relative;

  width: 100%;
  max-width: 1180px;

  margin: 0 auto;

  padding: 0 28px;
}


/* =========================================================
   15. SECTION HEADINGS
   ========================================================= */

.cfa-welcome h2,
.cfa-services h2,
.cfa-about h2,
.cfa-contact h2 {
  color: #0F172A;

  font-weight: 800;

  letter-spacing: -2px;

  line-height: 1.1;
}

.cfa-welcome h2 {
  max-width: 780px;

  margin: 0 0 18px;

  font-size:
    clamp(34px, 4.2vw, 52px);
}

.cfa-welcome-inner > p {
  max-width: 680px;

  margin: 0;

  color: #64748B;

  font-size: 17px;

  line-height: 1.8;
}


/* =========================================================
   16. WELCOME POINTS
   ========================================================= */

.cfa-welcome-points {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 22px;

  margin-top: 52px;
}

.cfa-welcome-point {
  position: relative;

  display: flex;

  gap: 18px;

  min-height: 170px;

  padding: 28px;

  overflow: hidden;

  background: #FFFFFF;

  border:
    1px solid #E2E8F0;

  border-radius: 16px;

  box-shadow:
    0 6px 22px rgba(15, 23, 42, 0.06);

  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.cfa-welcome-point::before {
  content: "";

  position: absolute;

  left: 0;
  top: 0;

  width: 100%;
  height: 4px;

  background:
    linear-gradient(
      90deg,
      #2563EB,
      #60A5FA
    );

  transform:
    scaleX(0);

  transform-origin: left;

  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.cfa-welcome-point:hover {
  transform:
    translateY(-8px);

  border-color:
    #BFDBFE;

  box-shadow:
    0 22px 50px rgba(15, 23, 42, 0.12);
}

.cfa-welcome-point:hover::before {
  transform:
    scaleX(1);
}


/* =========================================================
   17. WELCOME ICON
   ========================================================= */

.cfa-wp-icon {
  flex-shrink: 0;

  width: 52px;
  height: 52px;

  display: flex;

  align-items: center;
  justify-content: center;

  background:
    linear-gradient(
      145deg,
      #DBEAFE,
      #BFDBFE
    );

  color: #1D4ED8;

  border-radius: 14px;

  box-shadow:
    0 10px 22px rgba(37, 99, 235, 0.12);

  font-size: 12px;

  font-weight: 800;
}

.cfa-welcome-point b {
  display: block;

  margin-bottom: 8px;

  color: #0F172A;

  font-size: 17px;

  font-weight: 800;
}

.cfa-welcome-point div > span {
  display: block;

  color: #64748B;

  font-size: 14px;

  line-height: 1.7;
}


/* =========================================================
   18. SERVICES
   ========================================================= */

.cfa-services {
  padding: 105px 0;

  background:
    radial-gradient(
      circle at 92% 8%,
      rgba(96, 165, 250, 0.10),
      transparent 28%
    ),
    #F8FAFC;
}

.cfa-services-header {
  width: 100%;
  max-width: 1180px;

  margin: 0 auto 50px;

  padding: 0 28px;
}

.cfa-services-header h2 {
  max-width: 800px;

  margin: 0 0 18px;

  font-size:
    clamp(34px, 4.2vw, 52px);
}

.cfa-services-header p {
  max-width: 660px;

  margin: 0;

  color: #64748B;

  font-size: 17px;

  line-height: 1.8;
}


/* =========================================================
   19. SERVICES GRID
   ========================================================= */

.cfa-services-grid {
  width: 100%;
  max-width: 1180px;

  margin: 0 auto;

  padding: 0 28px;

  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 22px;
}


/* =========================================================
   20. SERVICE CARD
   ========================================================= */

.cfa-service-card {
  position: relative;

  min-height: 290px;

  display: flex;
  flex-direction: column;

  padding: 28px 25px;

  overflow: hidden;

  background: #FFFFFF;

  border:
    1px solid #E2E8F0;

  border-radius: 16px;

  box-shadow:
    0 6px 22px rgba(15, 23, 42, 0.06);

  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.cfa-service-card::before {
  content: "";

  position: absolute;

  left: 0;
  top: 0;

  width: 100%;
  height: 4px;

  background:
    linear-gradient(
      90deg,
      #2563EB,
      #60A5FA
    );

  transform:
    scaleX(0);

  transform-origin: left;

  transition:
    transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}

.cfa-service-card::after {
  content: "";

  position: absolute;

  right: -50px;
  bottom: -50px;

  width: 140px;
  height: 140px;

  background:
    radial-gradient(
      circle,
      rgba(96, 165, 250, 0.12),
      transparent 68%
    );

  border-radius: 50%;

  transition:
    transform 0.45s ease;
}

.cfa-service-card:hover {
  transform:
    translateY(-9px);

  border-color:
    #BFDBFE;

  box-shadow:
    0 22px 50px rgba(15, 23, 42, 0.12);
}

.cfa-service-card:hover::before {
  transform:
    scaleX(1);
}

.cfa-service-card:hover::after {
  transform:
    scale(1.4);
}


/* =========================================================
   21. SERVICE ICON
   ========================================================= */

.cfa-service-icon {
  position: relative;

  width: 54px;
  height: 54px;

  display: flex;

  align-items: center;
  justify-content: center;

  margin-bottom: 26px;

  background:
    linear-gradient(
      145deg,
      #DBEAFE,
      #BFDBFE
    );

  color: #1D4ED8;

  border-radius: 14px;

  box-shadow:
    0 10px 24px rgba(37, 99, 235, 0.12);

  font-size: 12px;

  font-weight: 800;

  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.cfa-service-card:hover .cfa-service-icon {
  transform:
    translateY(-3px)
    rotate(-4deg);
}

.cfa-service-card h4 {
  margin: 0 0 11px;

  color: #0F172A;

  font-size: 18px;

  line-height: 1.3;

  font-weight: 800;

  letter-spacing: -0.2px;
}

.cfa-service-card p {
  position: relative;
  z-index: 1;

  margin: 0;

  color: #64748B;

  font-size: 14px;

  line-height: 1.75;
}


/* =========================================================
   22. ABOUT
   ========================================================= */

.cfa-about {
  padding: 105px 0;

  overflow: hidden;

  background:
    linear-gradient(
      140deg,
      #1E293B 0%,
      #0F172A 100%
    );
}

.cfa-about::before {
  content: "";

  position: absolute;

  right: -170px;
  top: -190px;

  width: 460px;
  height: 460px;

  border-radius: 50%;

  border:
    1px solid rgba(96, 165, 250, 0.20);

  box-shadow:
    0 0 0 50px rgba(96, 165, 250, 0.05),
    0 0 0 100px rgba(96, 165, 250, 0.03);

  pointer-events: none;
}

.cfa-about-inner {
  position: relative;
  z-index: 2;

  width: 100%;
  max-width: 1180px;

  margin: 0 auto;

  padding: 0 28px;
}


/* =========================================================
   23. ABOUT LABEL
   ========================================================= */

.cfa-about .cfa-section-label {
  color: #93C5FD;

  background:
    rgba(96, 165, 250, 0.10);

  border-color:
    rgba(96, 165, 250, 0.20);
}


/* =========================================================
   24. ABOUT HEADING
   ========================================================= */

.cfa-about h2 {
  max-width: 820px;

  margin: 0 0 18px;

  color: #FFFFFF;

  font-size:
    clamp(34px, 4.2vw, 52px);
}

.cfa-about-inner > p {
  max-width: 740px;

  margin: 0;

  color:
    #CBD5E1;

  font-size: 17px;

  line-height: 1.8;
}


/* =========================================================
   25. TEAM GRID
   ========================================================= */

.cfa-team-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 22px;

  margin-top: 52px;
}


/* =========================================================
   26. TEAM CARD
   ========================================================= */

.cfa-team-card {
  position: relative;

  min-height: 210px;

  padding: 26px 22px;

  background:
    rgba(255, 255, 255, 0.06);

  border:
    1px solid rgba(255, 255, 255, 0.10);

  border-radius: 16px;

  box-shadow:
    0 14px 36px rgba(0, 0, 0, 0.18);

  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);

  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    background 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.cfa-team-card:hover {
  transform:
    translateY(-8px);

  background:
    rgba(255, 255, 255, 0.10);

  box-shadow:
    0 26px 54px rgba(0, 0, 0, 0.28);
}


/* =========================================================
   27. TEAM AVATAR
   ========================================================= */

.cfa-team-avatar {
  width: 56px;
  height: 56px;

  display: flex;

  align-items: center;
  justify-content: center;

  margin-bottom: 20px;

  background:
    linear-gradient(
      145deg,
      #2563EB,
      #1D4ED8
    );

  color: #FFFFFF;

  border-radius: 50%;

  box-shadow:
    0 10px 22px rgba(37, 99, 235, 0.25);

  font-size: 13px;

  font-weight: 800;

  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.cfa-team-card:hover .cfa-team-avatar {
  transform:
    translateY(-3px)
    rotate(4deg);
}

.cfa-team-card b {
  display: block;

  margin-bottom: 7px;

  color: #FFFFFF;

  font-size: 16px;

  font-weight: 800;
}

.cfa-team-card span {
  display: block;

  color: #CBD5E1;

  font-size: 13px;

  line-height: 1.65;
}


/* =========================================================
   28. COLLEGE
   ========================================================= */

.cfa-college {
  display: flex;

  align-items: center;

  flex-wrap: wrap;

  gap: 8px;

  margin-top: 36px !important;

  color: #FFFFFF !important;

  font-size: 14px !important;

  font-weight: 700;
}

.cfa-college span {
  color: #93C5FD;

  font-size: 16px;
}


/* =========================================================
   29. CONTACT
   ========================================================= */

.cfa-contact {
  padding: 105px 0;

  background:
    linear-gradient(
      180deg,
      #FFFFFF,
      #F8FAFC
    );
}

.cfa-contact-inner {
  width: 100%;
  max-width: 1180px;

  margin: 0 auto;

  padding: 0 28px;
}

.cfa-contact h2 {
  margin: 0 0 16px;

  font-size:
    clamp(34px, 4vw, 50px);
}

.cfa-contact-intro {
  max-width: 660px;

  margin: 0;

  color: #64748B;

  font-size: 17px;

  line-height: 1.8;
}


/* =========================================================
   30. CONTACT GRID
   ========================================================= */

.cfa-contact-grid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 22px;

  margin-top: 50px;
}


/* =========================================================
   31. CONTACT CARD
   ========================================================= */

.cfa-contact-card {
  position: relative;

  min-height: 170px;

  padding: 28px 26px;

  background: #FFFFFF;

  border:
    1px solid #E2E8F0;

  border-left:
    5px solid #2563EB;

  border-radius: 16px;

  box-shadow:
    0 6px 22px rgba(15, 23, 42, 0.06);

  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    border-left-color 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.cfa-contact-card:hover {
  transform:
    translateY(-7px);

  border-left-color:
    #1D4ED8;

  box-shadow:
    0 22px 50px rgba(15, 23, 42, 0.12);
}

.cfa-contact-card b {
  display: block;

  margin-bottom: 8px;

  color: #0F172A;

  font-size: 16px;

  font-weight: 800;
}

.cfa-contact-card span {
  display: block;

  color: #64748B;

  font-size: 14px;

  line-height: 1.75;
}


/* =========================================================
   32. ANIMATIONS
   ========================================================= */

@keyframes cfaFloat {
  from {
    transform:
      translateY(-50%)
      rotate(4deg);
  }

  to {
    transform:
      translateY(calc(-50% - 14px))
      rotate(2deg);
  }
}

@keyframes cfaFloatTwo {
  from {
    transform:
      translateY(40%)
      rotate(-6deg);
  }

  to {
    transform:
      translateY(28%)
      rotate(-3deg);
  }
}

@keyframes cfaPulse {
  0%,
  100% {
    box-shadow:
      0 0 0 4px rgba(96, 165, 250, 0.16);
  }

  50% {
    box-shadow:
      0 0 0 9px rgba(96, 165, 250, 0.04);
  }
}


/* =========================================================
   33. LARGE DESKTOP
   ========================================================= */

@media (min-width: 1200px) {

  .cfa-hero {
    min-height: 740px;

    padding-top: 125px;
    padding-bottom: 130px;
  }
}


/* =========================================================
   34. DESKTOP / TABLET
   ========================================================= */

@media (min-width: 992px) and (max-width: 1199px) {

  .cfa-hero-inner,
  .cfa-welcome-inner,
  .cfa-services-header,
  .cfa-services-grid,
  .cfa-about-inner,
  .cfa-contact-inner {
    max-width: 1080px;
  }

  .cfa-services-grid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .cfa-team-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .cfa-hero::after {
    right: 2%;

    opacity: 0.55;
  }
}


/* =========================================================
   35. TABLET
   ========================================================= */

@media (min-width: 768px) and (max-width: 991px) {

  .cfa-hero-inner,
  .cfa-welcome-inner,
  .cfa-services-header,
  .cfa-services-grid,
  .cfa-about-inner,
  .cfa-contact-inner {
    padding-left: 24px;
    padding-right: 24px;
  }

  .cfa-hero {
    min-height: 640px;

    padding: 90px 0 100px;
  }

  .cfa-hero h1 {
    max-width: 680px;

    font-size: 60px;

    letter-spacing: -2.6px;
  }

  .cfa-hero::after,
  .cfa-hero-inner::after {
    opacity: 0.25;
  }

  .cfa-welcome,
  .cfa-services,
  .cfa-about,
  .cfa-contact {
    padding: 85px 0;
  }

  .cfa-welcome-points,
  .cfa-services-grid,
  .cfa-team-grid,
  .cfa-contact-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }
}


/* =========================================================
   36. MOBILE TABLET
   ========================================================= */

@media (min-width: 576px) and (max-width: 767px) {

  .cfa-hero-inner,
  .cfa-welcome-inner,
  .cfa-services-header,
  .cfa-services-grid,
  .cfa-about-inner,
  .cfa-contact-inner {
    padding-left: 22px;
    padding-right: 22px;
  }

  .cfa-hero {
    min-height: auto;

    padding: 80px 0 90px;
  }

  .cfa-hero h1 {
    font-size: 52px;

    letter-spacing: -2.3px;
  }

  .cfa-hero-inner > p {
    font-size: 16px;
  }

  .cfa-hero::after,
  .cfa-hero-inner::after {
    display: none;
  }

  .cfa-welcome,
  .cfa-services,
  .cfa-about,
  .cfa-contact {
    padding: 75px 0;
  }

  .cfa-welcome-points,
  .cfa-services-grid,
  .cfa-team-grid,
  .cfa-contact-grid {
    grid-template-columns: 1fr;
  }
}


/* =========================================================
   37. MOBILE
   ========================================================= */

@media (max-width: 575px) {

  .cfa-hero-inner,
  .cfa-welcome-inner,
  .cfa-services-header,
  .cfa-services-grid,
  .cfa-about-inner,
  .cfa-contact-inner {
    padding-left: 18px;
    padding-right: 18px;
  }

  .cfa-hero {
    min-height: auto;

    padding: 72px 0 80px;
  }

  .cfa-hero::after,
  .cfa-hero-inner::after {
    display: none;
  }

  .cfa-hero-badge {
    margin-bottom: 20px;

    font-size: 12px;
  }

  .cfa-hero h1 {
    max-width: 100%;

    margin-bottom: 28px;

    font-size: 40px;

    letter-spacing: -1.8px;
  }

  .cfa-hero h1::after {
    width: 66px;

    height: 4px;
  }

  .cfa-hero-inner > p {
    font-size: 15px;
  }

  .cfa-hero-btn {
    width: 100%;
  }

  .cfa-hero-note {
    font-size: 12px;

    flex-wrap: wrap;
  }

  .cfa-welcome,
  .cfa-services,
  .cfa-about,
  .cfa-contact {
    padding: 70px 0;
  }

  .cfa-welcome h2,
  .cfa-services h2,
  .cfa-about h2,
  .cfa-contact h2 {
    font-size: 32px;

    letter-spacing: -1.3px;
  }

  .cfa-welcome-points,
  .cfa-services-grid,
  .cfa-team-grid,
  .cfa-contact-grid {
    grid-template-columns: 1fr;
  }

  .cfa-welcome-point,
  .cfa-service-card,
  .cfa-team-card {
    min-height: auto;

    padding: 24px;
  }
}


/* =========================================================
   38. SMALL MOBILE
   ========================================================= */

@media (max-width: 399px) {

  .cfa-hero-inner,
  .cfa-welcome-inner,
  .cfa-services-header,
  .cfa-services-grid,
  .cfa-about-inner,
  .cfa-contact-inner {
    padding-left: 15px;
    padding-right: 15px;
  }

  .cfa-hero {
    padding: 62px 0 70px;
  }

  .cfa-hero h1 {
    font-size: 35px;

    letter-spacing: -1.5px;
  }

  .cfa-welcome h2,
  .cfa-services h2,
  .cfa-about h2,
  .cfa-contact h2 {
    font-size: 28px;
  }
}


/* =========================================================
   39. REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .cfa-hero *,
  .cfa-welcome *,
  .cfa-services *,
  .cfa-about *,
  .cfa-contact *,
  .cfa-hero::after,
  .cfa-hero-inner::after {
    animation: none !important;

    transition: none !important;
  }
}

sp_widget.script:
(function() {

    // Native Service Portal login URL
    data.loginUrl = '/sp?id=food_service_login_page';

    // Current year for footer
    data.year = new GlideDateTime().getYearLocalTime();

})();
